CREATE TABLE flash_sale_reservation (request_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,activity_id BIGINT NOT NULL,user_id BIGINT NOT NULL,idempotency_digest BINARY(32) NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'reserved',order_id BIGINT NULL,failure_code VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NULL,reserved_at DATETIME(6) NOT NULL,payment_expires_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(request_id),CONSTRAINT uk_flash_sale_reservation_user UNIQUE(activity_id,user_id),CONSTRAINT uk_flash_sale_reservation_digest UNIQUE(activity_id,user_id,idempotency_digest),CONSTRAINT uk_flash_sale_reservation_order UNIQUE(order_id),KEY idx_flash_sale_reservation_owner(user_id,created_at DESC,request_id),CONSTRAINT ck_flash_sale_request_id CHECK(REGEXP_LIKE(request_id,'^fsr_[1-9a-z][0-9a-z]{0,12}_[a-f0-9]{32}$','c')),CONSTRAINT ck_flash_sale_reservation_status CHECK(status IN ('reserved','order_ready','failed','expired')),CONSTRAINT ck_flash_sale_reservation_order CHECK((status IN ('reserved','failed') AND order_id IS NULL) OR (status IN ('order_ready','expired') AND order_id IS NOT NULL)),CONSTRAINT ck_flash_sale_reservation_failure CHECK((status='failed' AND failure_code IS NOT NULL AND CHAR_LENGTH(TRIM(failure_code))>0) OR (status<>'failed' AND failure_code IS NULL)),CONSTRAINT fk_flash_sale_reservation_activity FOREIGN KEY(activity_id) REFERENCES flash_sale_activity(id) ON DELETE RESTRICT,CONSTRAINT fk_flash_sale_reservation_user FOREIGN KEY(user_id) REFERENCES user_account(id) ON DELETE RESTRICT,CONSTRAINT fk_flash_sale_reservation_order FOREIGN KEY(order_id) REFERENCES purchase_order(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
